#include "DiamondTrap.hpp"

DiamondTrap::DiamondTrap(const std::string& value): ClapTrap(value + "_clap_name"), FragTrap(value), ScavTrap(value), name(value)
{
    hitPoints = 100;
    energyPoints = 50;
    attackDamage = 30;
    std::cout << "DiamondTrap " << name << " constructor called." << std::endl;
}

DiamondTrap::DiamondTrap(const DiamondTrap& other): ClapTrap(other), FragTrap(other), ScavTrap(other), name(other.name)
{
    std::cout << "DiamondTrap " << name << " copy constructor called." << std::endl;
}

DiamondTrap& DiamondTrap::operator=(const DiamondTrap& other)
{
    if (this != &other)
    {
        ClapTrap::operator=(other);
        name = other.name;
    }
    std::cout << "DiamondTrap " << name << " assignment operator called." << std::endl;
    return *this;
}

DiamondTrap::~DiamondTrap()
{
    std::cout << "DiamondTrap " << name << " destructor called." << std::endl;
}

const std::string& DiamondTrap::getDiamondName() const
{
    return name;
}

void DiamondTrap::setDiamondName(const std::string& value)
{
    name = value;
}

void DiamondTrap::attack(const std::string& target)
{
    ScavTrap::attack(target);
}

void DiamondTrap::whoAmI()
{
    std::cout
        << "DiamondTrap name: " << name
        << ", ClapTrap name: " << ClapTrap::name
        << std::endl;
}
